package webui

import (
	"regexp"

	"nday.land/nday/internal/tags"
)

// Tag icons (docs/tagicons.md): product and ecosystem tags show their brand
// mark in front of the label. The marks come from Simple Icons (CC0-1.0),
// generated by tools/tagicons from tags.Icons into two static files served
// from this site: static/tagicons.svg (a <symbol> sprite) and
// static/tagicons.css (the same marks as CSS masks). The icon is decorative
// (aria-hidden); the label stays the chip's accessible name. A tag without
// an icon renders exactly as before.

// Tag icon renderings. TagIconUse references the sprite:
//
//	<svg class="tgi" aria-hidden="true" focusable="false"><use href="/static/tagicons.<hash>.svg#php"/></svg>
//
// TagIconMask needs no external reference: an empty
// <span class="tgi" data-i="php"> masked by a rule of tagicons.css, which
// base.tmpl links only in this mode. Flip TagIconMode if a browser refuses
// the sprite.
const (
	TagIconUse  = "use"
	TagIconMask = "mask"
)

// TagIconMode is the rendering every page uses.
const TagIconMode = TagIconUse

// tagIconSymbols are the symbol ids of the embedded sprite, read once.
var tagIconSymbols = func() map[string]bool {
	b, err := staticFS.ReadFile("static/tagicons.svg")
	if err != nil {
		panic("webui: no tag icon sprite: " + err.Error())
	}
	ids := map[string]bool{}
	for _, m := range regexp.MustCompile(`<symbol id="([a-z0-9]+)"`).FindAllSubmatch(b, -1) {
		ids[string(m[1])] = true
	}
	return ids
}()

// tagIcon returns the symbol id of slug's icon, "" when it has none (or the
// sprite lacks it, which TestTagIconsMatchSprite rules out).
func tagIcon(slug string) string {
	if id := tags.IconFor(slug); tagIconSymbols[id] {
		return id
	}
	return ""
}
